task_graph:
[
  {
    "id": "task_1",
    "description": "Retrieve JOLTS event data including surprises",
    "agent": "eventdata_puller_agent",
    "params": {
      "event_name": "JOLTS",
      "lookback_days": 365
    },
    "dependencies": []
  },
  {
    "id": "task_2",
    "description": "Fetch TY price data for the hour after each JOLTS event",
    "agent": "market_data_agent",
    "params": {
      "template": "select * from ohlcv_1m where symbol='TY' and time >= :event_time and time < :event_time + interval '1 hour'",
      "params": {
        "event_time": "{task_1.event_time}"
      },
      "columns": ["open", "high", "low", "close"],
      "limit": 60
    },
    "dependencies": ["task_1"]
  },
  {
    "id": "task_3",
    "description": "Calculate correlation between JOLTS surprises and TY price changes",
    "agent": "analytics_agent",
    "params": {
      "analysis_type": "correlation",
      "params": {
        "x_series": "{task_1.surprises}",
        "y_series": "{task_2.price_changes}"
      },
      "generate_plot": false
    },
    "dependencies": ["task_1", "task_2"]
  },
  {
    "id": "task_4",
    "description": "Consolidate findings and provide final analysis",
    "agent": "runner_agent",
    "params": {
      "query": "What is the correlation between JOLTS surprise and TY price change in the hour after?",
      "worker_outputs": ["task_3.correlation_result"],
      "planning_table": "task_1, task_2, task_3",
      "run_id": "run_12345"
    },
    "dependencies": ["task_3"]
  }
]
